//! The input must be generated by the pinned Core10 implementation, never by
//! relabelling a current database. Only a temporary copy is upgraded here.
use exomind_core::{Core, ProfileId, SummaryArtifactRecord, TimelinePeriodQuery};
use rusqlite::{Connection, OpenFlags, types::Value};
use serde_json::Value as Json;
use sha2::{Digest, Sha256};
use std::{fs, path::PathBuf};

fn rows(connection: &Connection, sql: &str) -> Vec<Vec<Value>> {
    let mut statement = connection.prepare(sql).unwrap();
    let columns = statement.column_count();
    statement
        .query_map([], |row| (0..columns).map(|index| row.get(index)).collect())
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap()
}

#[test]
#[ignore = "requires a pinned old Core10 database via EXOMIND_CORE_SCHEMA10_FIXTURE"]
fn pinned_core10_database_upgrades_without_rewriting_facts_or_receipts() {
    let fixture = PathBuf::from(
        std::env::var_os("EXOMIND_CORE_SCHEMA10_FIXTURE")
            .expect("generate the immutable synthetic Core10 fixture first"),
    );
    let manifest: Json =
        serde_json::from_slice(&fs::read(fixture.join("manifest.json")).unwrap()).unwrap();
    assert_eq!(
        manifest["baseline_commit"],
        "5708e0baf5cdc896559fab5172dc13805531ba33"
    );
    assert_eq!(manifest["database_schema"], 10);
    let original = fs::read(fixture.join("beta-core.sqlite3")).unwrap();
    assert_eq!(
        format!("{:x}", Sha256::digest(&original)),
        manifest["database_sha256"]
    );
    let target = tempfile::tempdir().unwrap();
    let database_path = target.path().join("beta-core.sqlite3");
    fs::write(&database_path, &original).unwrap();
    let readonly =
        || Connection::open_with_flags(&database_path, OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();
    let before = readonly();
    assert_eq!(
        before
            .pragma_query_value::<i64, _>(None, "user_version", |row| row.get(0))
            .unwrap(),
        10
    );
    let event_query = "SELECT local_seq,event_id,profile_id,digest,CAST(body AS BLOB) FROM events ORDER BY local_seq";
    let receipt_query = "SELECT * FROM command_receipts ORDER BY rowid";
    let identity_query = "SELECT * FROM identity ORDER BY singleton";
    let events = rows(&before, event_query);
    let receipts = rows(&before, receipt_query);
    let identity = rows(&before, identity_query);
    assert!(!events.is_empty());
    assert!(!receipts.is_empty());
    drop(before);

    let core = Core::open(target.path()).unwrap();
    let after = readonly();
    assert_eq!(
        after
            .pragma_query_value::<i64, _>(None, "user_version", |row| row.get(0))
            .unwrap(),
        11
    );
    assert_eq!(rows(&after, event_query), events);
    assert_eq!(rows(&after, receipt_query), receipts);
    assert_eq!(rows(&after, identity_query), identity);
    let record: SummaryArtifactRecord =
        serde_json::from_slice(&fs::read(fixture.join("summary-body.json")).unwrap()).unwrap();
    assert_eq!(
        record.computed_digest().unwrap(),
        manifest["artifact_digest"]
    );
    assert_eq!(record.snapshot.digest, manifest["snapshot_digest"]);
    let stored: Vec<u8> = after
        .query_row(
            "SELECT CAST(body AS BLOB) FROM events WHERE event_id=?1",
            [record.event_id.to_string()],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(stored, fs::read(fixture.join("summary-body.json")).unwrap());
    let profile: ProfileId = manifest["profile_id"].as_str().unwrap().parse().unwrap();
    let page = core
        .timeline_period_page(
            &core.local_human(profile).unwrap(),
            profile,
            &TimelinePeriodQuery {
                from_ms: 0,
                to_ms: i64::MAX,
                before: None,
                through: None,
                limit: 100,
                search: None,
                tag: None,
            },
        )
        .unwrap();
    assert!(!page.items.is_empty());
    drop(after);
    drop(core);
    let reopened = Core::open(target.path()).unwrap();
    assert_eq!(rows(&readonly(), event_query), events);
    drop(reopened);
    assert_eq!(
        fs::read(fixture.join("beta-core.sqlite3")).unwrap(),
        original,
        "immutable input was never opened for writing"
    );
}
